@Bean
AccountClient accountClient(RestClient.Builder builder) {
    var settings = ClientHttpRequestFactorySettings.defaults()
            .withConnectTimeout(Duration.ofMillis(500))
            .withReadTimeout(Duration.ofMillis(800));

    var rest = builder
            .baseUrl("http://localhost:8080")
            .requestFactory(ClientHttpRequestFactoryBuilder.detect().build(settings))
            .build();

    return HttpServiceProxyFactory
            .builderFor(RestClientAdapter.create(rest))
            .build()
            .createClient(AccountClient.class);
}

package io.ledgerflow.ledger.config;

import org.springframework.context.annotation.Configuration;
import org.springframework.resilience.annotation.EnableResilientMethods;

@Configuration
@EnableResilientMethods
class ResilienceConfig { }

package io.ledgerflow.ledger.adapter.out.account;

import org.springframework.resilience.annotation.Retryable;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClientException;

import java.time.Duration;
import java.util.UUID;

/** Everything the rest of the app uses to reach account goes through here. */
@Component
public class AccountGateway {

    private final AccountClient client;

    AccountGateway(AccountClient client) { this.client = client; }

    @Retryable(maxAttempts = 3, delay = 200, includes = RestClientException.class)
    public AccountClient.AccountView account(UUID accountId) {
        return client.account(accountId);
    }
}

