private final Map<UUID, AccountClient.AccountView> lastKnownGood = new ConcurrentHashMap<>();

@Retryable(maxAttempts = 3, delay = 200, includes = RestClientException.class)
public AccountClient.AccountView account(UUID accountId) {
    var view = client.account(accountId);
    lastKnownGood.put(accountId, view);
    return view;
}

/** Called when every attempt above has failed. */
public AccountClient.AccountView accountOrLastKnown(UUID accountId) {
    try {
        return account(accountId);
    } catch (RestClientException e) {
        var cached = lastKnownGood.get(accountId);
        if (cached == null) throw e;             // nothing to fall back to
        log.warn("account unavailable, serving cached balance view for {}", accountId);
        return cached;
    }
}
